 *
 * Flow: validate input → check stock → get sequence number → insert sale header
 *       → insert line items → insert payment → insert allocation → insert stock movements
 * All-or-nothing: any failure rolls back everything.
 *
 * @param rawInput — Unvalidated input object (will be validated via Zod)
 * @returns Sale result with created entities
 */
export async function createDirectSale(rawInput: unknown): Promise<SaleResult> {
  // Validate input via Zod schema
  const parsed = createDirectSaleInputSchema.safeParse(rawInput)
  if (!parsed.success) {
    throw new Error(`Invalid sale input: ${parsed.error.message}`)
  }

  const input = parsed.data as CreateDirectSaleInput

  // ---------------------------------------------------------------------------
  // Step 1: Validate stock availability for all line items
  // ---------------------------------------------------------------------------
  const stockRequests = input.lineItems.map((item) => ({
    partId: item.partId,
    requestedQuantity: item.quantity
  }))

  const stockResult = await validateStockAvailability(stockRequests)
  if (!stockResult.valid) {
    throw new InsufficientStockError(stockResult.shortfalls)
  }

  // ---------------------------------------------------------------------------
  // Step 2: Get sale number from sequence table (atomic increment)
  // ---------------------------------------------------------------------------
  const saleNumberSeq = await getNextValue('sale')
  const saleNumber = `SA-${String(saleNumberSeq).padStart(4, '0')}`

  // ---------------------------------------------------------------------------
  // Step 3: Fetch VAT rates needed for line item calculations
  // ---------------------------------------------------------------------------
  const allVatRates = await db.select({ id: vatRates.id, rate: vatRates.rate }).from(vatRates)
  const vatRatesMap = new Map<string, number>()
  for (const row of allVatRates) {
    vatRatesMap.set(row.id, Number(row.rate))
  }

  // ---------------------------------------------------------------------------
  // Step 4: Compute line item totals using shared pricing lib
  // ---------------------------------------------------------------------------
  const lineItemsData = input.lineItems.map((item) => {
    const vatRateBps = vatRatesMap.get(item.vatRateId) ?? 0
    const totals = computeLineTotals(item.unitPriceNet, item.quantity, item.discountPercent, vatRateBps)

    return {
      partId: item.partId,
      quantity: item.quantity,
      unitPriceNet: item.unitPriceNet,
      vatRateId: item.vatRateId,
      description: item.description,
      discountPercent: item.discountPercent ?? null,
      lineTotalNet: totals.net,
      lineTotalVat: totals.vat,
      lineTotalGross: totals.gross,
      lineType: 'part' as const
    }
  })

  const subtotalNet = lineItemsData.reduce((sum, item) => sum + item.lineTotalNet, 0)
  const vatTotal = lineItemsData.reduce((sum, item) => sum + item.lineTotalVat, 0)
  const totalGross = subtotalNet + vatTotal

  // ---------------------------------------------------------------------------
  // Step 5: Execute single transaction — all inserts or nothing
  // ---------------------------------------------------------------------------
  const saleId = crypto.randomUUID()
  const paymentId = crypto.randomUUID()

  const client = sqliteDb as Database.Database
  const run = (sqlStr: string, params?: unknown[]) => {
    return client.prepare(sqlStr).run(...(params ?? []))
  }

  try {
    // Begin transaction
    run('BEGIN TRANSACTION')

    // Insert sale header
    run(
      'INSERT INTO sales (id, sale_number, customer_id, source_type, source_id, status, subtotal_net, vat_total, total_gross, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)',
      [saleId, saleNumber, input.customerId ?? null, 'direct_sale', null, 'completed', subtotalNet, vatTotal, totalGross, Date.now()]
    )

    const now = Date.now()

    // Insert line items
    for (const item of lineItemsData) {
      const lineItemId = crypto.randomUUID()
      run(
        'INSERT INTO sale_line_items (id, sale_id, line_type, part_id, description, quantity, unit_price_net, vat_rate_id, discount_percent, line_total_net, line_total_vat, line_total_gross, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)',
        [lineItemId, saleId, item.lineType, item.partId, item.description, item.quantity, item.unitPriceNet, item.vatRateId, item.discountPercent, item.lineTotalNet, item.lineTotalVat, item.lineTotalGross, now]
      )
    }

    // Insert payment record
    run(
      'INSERT INTO payments (id, method, amount, created_at) VALUES (?, ?, ?, ?)',
      [paymentId, input.paymentMethod, totalGross, now]
    )

    // Insert payment allocation (payment → sale)
    run(
      'INSERT INTO payment_allocations (id, payment_id, target_type, target_id, allocated_amount) VALUES (?, ?, ?, ?, ?)',
      [crypto.randomUUID(), paymentId, 'sale', saleId, totalGross]
    )

    // Insert stock movements (negative deltas for each part sold)
    for (const item of input.lineItems) {
      run(
        'INSERT INTO stock_movements (id, part_id, quantity_delta, reason, reference_type, reference_id, created_at) VALUES (?, ?, ?, ?, ?, ?, ?)',
        [crypto.randomUUID(), item.partId, -item.quantity, 'sale', 'sale', saleId, now]
      )
    }

    // Commit transaction
    run('COMMIT')
  } catch (err) {
    // Rollback on any error
    try { run('ROLLBACK') }
    catch {}
    throw err
  }

